import { FRAGMENT, VERTEX } from './side-rays-shaders';
import type {
  SideRaysEngine,
  SideRaysFrame,
  SideRaysOrigin,
  SideRaysProps,
  SideRaysSettings,
} from './types';

interface LinkedProgram {
  program: WebGLProgram;
  uniforms: Record<string, WebGLUniformLocation | null>;
}

type Rgb = [number, number, number];

const PIXEL_BUDGET = 2.4e6;
const TAU = Math.PI * 2;

const ORIGINS: Record<SideRaysOrigin, SideRaysFrame> = {
  'top-right': { flipX: 0, flipY: 0, side: 0 },
  'top-left': { flipX: 1, flipY: 0, side: 0 },
  'bottom-right': { flipX: 0, flipY: 1, side: 0 },
  'bottom-left': { flipX: 1, flipY: 1, side: 0 },
  right: { flipX: 0, flipY: 0, side: 1 },
  left: { flipX: 1, flipY: 0, side: 1 },
};

const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value));

const wrapAngle = (angle: number): number =>
  ((((angle + Math.PI) % TAU) + TAU) % TAU) - Math.PI;

function parseColor(value: string | undefined): Rgb {
  const text = String(value || '').trim();
  const hex = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(text);
  const digits = hex?.[1];
  if (digits) {
    const full =
      digits.length === 3
        ? digits.replace(/./g, (digit) => digit + digit)
        : digits;
    return [
      Number.parseInt(full.slice(0, 2), 16) / 255,
      Number.parseInt(full.slice(2, 4), 16) / 255,
      Number.parseInt(full.slice(4, 6), 16) / 255,
    ];
  }
  const rgb = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/i.exec(text);
  if (rgb) {
    const channel = (part: string | undefined) =>
      clamp(Number.parseFloat(part ?? '255') / 255, 0, 1);
    return [channel(rgb[1]), channel(rgb[2]), channel(rgb[3])];
  }
  return [1, 1, 1];
}

export function normalizeSideRays(
  p: SideRaysProps,
  reduce: boolean,
): SideRaysSettings {
  return {
    colorA: parseColor(p.rayColor1 ?? '#FFC46B'),
    colorB: parseColor(p.rayColor2 ?? '#96c8ff'),
    blend: clamp(p.blend ?? 0.6, 0, 1),
    frame: ORIGINS[p.origin ?? 'top-right'] ?? ORIGINS['top-right'],
    speed: Math.max(0, p.speed ?? 2.5) * 0.4,
    intensity: Math.max(0, p.intensity ?? 2) * 0.75,
    spread: clamp(p.spread ?? 2, 0.1, 8) * 0.225,
    density: clamp(p.density ?? 5, 1, 40),
    sharpness: clamp(p.sharpness ?? 0.5, 0, 1),
    tilt: (clamp(p.tilt ?? 0, -180, 180) * Math.PI) / 180,
    falloff: clamp(p.falloff ?? 1.6, 0.2, 6),
    glow: Math.max(0, p.glow ?? 1) * 1.2,
    saturation: Math.max(0, p.saturation ?? 1),
    dust: clamp(p.dust ?? 0, 0, 1),
    followMouse: p.followMouse ?? true,
    mouseInfluence: clamp(p.mouseInfluence ?? 0.5, 0, 1),
    intro: p.intro ?? true,
    light: p.lightMode ?? false,
    opacity: clamp(p.opacity ?? 1, 0, 1),
    maxRatio: clamp(p.maxDevicePixelRatio ?? 2, 0.5, 3),
    reduce,
  };
}

function geometryFor(
  frame: SideRaysFrame,
  aspect: number,
): { source: [number, number]; heading: number } {
  return {
    source: frame.side
      ? [aspect * 0.5 + 0.42, 0.3]
      : [aspect * 0.5 + 0.1, 0.62],
    heading: frame.side ? 3.42 : -2.48,
  };
}

function compile(
  gl: WebGL2RenderingContext,
  type: number,
  source: string,
): WebGLShader | null {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.error(gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

function link(gl: WebGL2RenderingContext): LinkedProgram | null {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
  const program = vertex && fragment ? gl.createProgram() : null;
  if (!vertex || !fragment || !program) {
    if (vertex) gl.deleteShader(vertex);
    if (fragment) gl.deleteShader(fragment);
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.error(gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Record<string, WebGLUniformLocation | null> = {};
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let index = 0; index < count; index++) {
    const info = gl.getActiveUniform(program, index);
    if (info) uniforms[info.name] = gl.getUniformLocation(program, info.name);
  }
  return { program, uniforms };
}

export function createSideRays(
  container: HTMLElement,
  canvas: HTMLCanvasElement,
  read: () => SideRaysSettings,
  options: { reveal: boolean; seed: number; pageVisible: boolean },
): SideRaysEngine | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'high-performance',
  });
  const shader = gl ? link(gl) : null;
  if (!gl || !shader) return null;

  const vao = gl.createVertexArray();
  const size = { width: 1, height: 1 };
  const pointer = { x: 0, y: 0, inside: false };
  const aim = { value: 0, velocity: 0 };
  const focus = { angle: 0, strength: 0 };
  const initial = read();
  let time = options.seed * 100;
  let reveal = options.reveal && initial.intro && !initial.reduce ? 0 : 1;
  let raf = 0;
  let last = 0;
  let visible = true;
  let pageVisible = options.pageVisible;
  let lost = false;

  const resize = () => {
    const s = read();
    const rect = container.getBoundingClientRect();
    const cssWidth = Math.max(1, rect.width);
    const cssHeight = Math.max(1, rect.height);
    const ratio = Math.min(
      window.devicePixelRatio || 1,
      s.maxRatio,
      Math.sqrt(PIXEL_BUDGET / (cssWidth * cssHeight)),
    );
    const width = Math.max(1, Math.round(cssWidth * ratio));
    const height = Math.max(1, Math.round(cssHeight * ratio));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    size.width = cssWidth;
    size.height = cssHeight;
  };

  const pointerAngle = (s: SideRaysSettings): number => {
    let x = (pointer.x - size.width / 2) / size.height;
    let y = (size.height / 2 - pointer.y) / size.height;
    if (s.frame.flipX) x = -x;
    if (s.frame.flipY) y = -y;
    const { source, heading } = geometryFor(s.frame, size.width / size.height);
    return wrapAngle(
      Math.atan2(y - source[1], x - source[0]) - heading - s.tilt,
    );
  };

  const frame = (now: number) => {
    raf = 0;
    if (lost) return;
    const s = read();
    const reduced = s.reduce;
    const dt = clamp((now - last) / 1000 || 0, 0, 0.05);
    last = Math.max(last, now);
    time += dt * s.speed * (reduced ? 0.3 : 1);
    if (reveal < 1) reveal = Math.min(1, reveal + dt / 1.6);

    const tracking = s.followMouse && pointer.inside && !reduced;
    const pointed = tracking ? pointerAngle(s) : 0;
    const target = tracking
      ? clamp(pointed, -s.spread, s.spread) * s.mouseInfluence
      : 0;
    const focusTarget = tracking ? s.mouseInfluence : 0;
    const ease = 1 - Math.exp(-dt * 6);
    if (tracking) {
      focus.angle +=
        (clamp(pointed - aim.value, -s.spread * 1.5, s.spread * 1.5) -
          focus.angle) *
        ease;
    }
    focus.strength += (focusTarget - focus.strength) * ease;
    const stiffness = 18;
    const damping = 2 * Math.sqrt(stiffness);
    aim.velocity +=
      ((target - aim.value) * stiffness - aim.velocity * damping) * dt;
    aim.value += aim.velocity * dt;

    const u = shader.uniforms;
    const at = (name: string) => u[name] ?? null;
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.useProgram(shader.program);
    gl.bindVertexArray(vao);
    gl.uniform2f(at('uResolution'), canvas.width, canvas.height);
    gl.uniform1f(at('uTime'), time);
    gl.uniform3f(at('uColorA'), s.colorA[0], s.colorA[1], s.colorA[2]);
    gl.uniform3f(at('uColorB'), s.colorB[0], s.colorB[1], s.colorB[2]);
    gl.uniform1f(at('uBlend'), s.blend);
    gl.uniform1f(at('uIntensity'), s.intensity);
    gl.uniform1f(at('uSpread'), s.spread);
    gl.uniform1f(at('uDensity'), s.density);
    gl.uniform1f(at('uSharpness'), s.sharpness);
    gl.uniform1f(at('uFalloff'), s.falloff);
    gl.uniform1f(at('uGlow'), s.glow);
    gl.uniform1f(at('uSaturation'), s.saturation);
    gl.uniform1f(at('uDust'), s.dust);
    gl.uniform1f(at('uOpacity'), s.opacity);
    gl.uniform1f(at('uReveal'), 1 - Math.pow(1 - reveal, 3));
    gl.uniform1f(at('uLight'), s.light ? 1 : 0);
    gl.uniform3f(at('uFrame'), s.frame.flipX, s.frame.flipY, s.frame.side);
    gl.uniform1f(at('uAim'), s.tilt + aim.value);
    gl.uniform3f(
      at('uFocus'),
      focus.angle,
      Math.max(0.06, s.spread * 0.25),
      focus.strength * 1.4,
    );
    gl.uniform1f(at('uSway'), reduced ? 0 : 1);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    const settling =
      Math.abs(target - aim.value) > 1e-4 ||
      Math.abs(aim.velocity) > 1e-4 ||
      Math.abs(focusTarget - focus.strength) > 1e-3;
    const busy = (s.speed > 0 && !reduced) || reveal < 1 || settling;
    if (busy && visible && pageVisible) raf = requestAnimationFrame(frame);
  };

  const wake = () => {
    if (raf || lost || !visible || !pageVisible) return;
    last = performance.now();
    raf = requestAnimationFrame(frame);
  };

  const leave = () => {
    pointer.inside = false;
    wake();
  };

  return {
    resize,
    wake() {
      resize();
      wake();
    },
    setVisible(next) {
      visible = next;
      wake();
    },
    setPageVisible(next) {
      pageVisible = next;
      wake();
    },
    pointerMove(event) {
      const rect = container.getBoundingClientRect();
      pointer.x = event.clientX - rect.left;
      pointer.y = event.clientY - rect.top;
      pointer.inside =
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom;
      wake();
    },
    pointerUp(event) {
      if (event.pointerType !== 'mouse') leave();
    },
    pointerLeave: leave,
    contextLost() {
      lost = true;
      cancelAnimationFrame(raf);
      raf = 0;
    },
    destroy() {
      cancelAnimationFrame(raf);
      raf = 0;
      if (!gl.isContextLost()) {
        gl.deleteVertexArray(vao);
        gl.deleteProgram(shader.program);
        gl.getExtension('WEBGL_lose_context')?.loseContext();
      }
    },
  };
}

export const VERTEX = `#version 300 es
const vec2 corners[3] = vec2[3](vec2(-1.0, -1.0), vec2(3.0, -1.0), vec2(-1.0, 3.0));
void main() {
  gl_Position = vec4(corners[gl_VertexID], 0.0, 1.0);
}`;

export const FRAGMENT = `#version 300 es
precision highp float;
uniform vec2 uResolution;
uniform float uTime;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform float uBlend;
uniform float uIntensity;
uniform float uSpread;
uniform float uDensity;
uniform float uSharpness;
uniform float uFalloff;
uniform float uGlow;
uniform float uSaturation;
uniform float uDust;
uniform float uOpacity;
uniform float uReveal;
uniform float uLight;
uniform vec3 uFrame;
uniform float uAim;
uniform vec3 uFocus;
uniform float uSway;
out vec4 fragColor;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  vec2 w = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

float shafts(float u, float t, float seed, float aa) {
  float sway = (0.4 * sin(t * 0.31 + seed) + 0.24 * sin(t * 0.17 + seed * 2.3)) * uSway;
  float n = 0.7 * noise(vec2(u + sway + seed, t * 0.3)) + 0.3 * noise(vec2(u * 2.4 + sway * 1.5 + seed * 1.7, t * 0.45 + 3.0));
  float width = mix(0.5, 0.1, uSharpness);
  float s = mix(smoothstep(0.5 - width, 0.5 + width, n), 0.5, aa);
  return mix(0.05, 1.0, s);
}

float motes(vec2 p, float cell, float t, float seed) {
  p += vec2(t * 0.021, -t * 0.013) + seed * 7.31;
  vec2 grid = p / cell;
  vec2 id = floor(grid);
  vec2 f = grid - id;
  float h = hash(id + seed);
  if (h > 0.5) return 0.0;
  vec2 center = 0.25 + 0.5 * vec2(hash(id + 1.7 + seed), hash(id + 3.1 + seed));
  center += 0.1 * vec2(sin(t * 0.7 + h * 31.0), cos(t * 0.6 + h * 23.0));
  float size = mix(0.035, 0.09, hash(id + 5.3 + seed));
  float edge = length(fwidth(grid)) * 0.7;
  float twinkle = 0.55 + 0.45 * sin(t * 1.9 + h * 41.0);
  return (1.0 - smoothstep(size - edge, size + edge, length(f - center))) * twinkle;
}

void main() {
  float aspect = uResolution.x / uResolution.y;
  vec2 q = (gl_FragCoord.xy - 0.5 * uResolution) / uResolution.y;
  if (uFrame.x > 0.5) q.x = -q.x;
  if (uFrame.y > 0.5) q.y = -q.y;
  vec2 source = uFrame.z > 0.5 ? vec2(aspect * 0.5 + 0.42, 0.3) : vec2(aspect * 0.5 + 0.1, 0.62);
  float heading = (uFrame.z > 0.5 ? 3.42 : -2.48) + uAim + 0.035 * sin(uTime * 0.21) * uSway;
  vec2 v = q - source;
  float r = length(v);
  float angle = mod(atan(v.y, v.x) - heading + 3.14159265, 6.28318531) - 3.14159265;
  float t = uTime;
  float u = angle * uDensity;
  float aa = smoothstep(0.12, 0.45, fwidth(u));
  float offset = uSpread * 0.22;
  float fanA = exp(-pow((angle + offset) / uSpread, 2.0) * 1.4);
  float fanB = exp(-pow((angle - offset) / (uSpread * 1.15), 2.0) * 1.4);
  float focus = 1.0 + uFocus.z * exp(-pow((angle - uFocus.x) / uFocus.y, 2.0));
  float lightA = fanA * shafts(u, t, 0.0, aa) * focus;
  float lightB = fanB * shafts(u * 0.83, t * 0.6, 17.0, aa) * focus;
  float reach = 1.0 / (1.0 + pow(r / 0.4, uFalloff));
  vec3 glowColor = mix(uColorA, uColorB, uBlend);
  vec3 light = (uColorA * lightA * (1.0 - uBlend) + uColorB * lightB * uBlend) * 2.0 * reach;
  light += glowColor * uGlow * exp(-pow(r / 0.4, 2.0));
  if (uDust > 0.0) {
    float sparkle = motes(q, 0.06, t, 0.0) + 0.7 * motes(q, 0.038, t * 0.8, 9.0);
    light += mix(glowColor, vec3(1.0), 0.6) * sparkle * (lightA + lightB) * reach * uDust * 2.5;
  }
  light *= uIntensity * (1.0 - smoothstep(uReveal * 2.6 - 0.45, uReveal * 2.6, r)) * smoothstep(0.0, 0.35, uReveal);
  float gray = dot(light, vec3(0.2126, 0.7152, 0.0722));
  light = max(mix(vec3(gray), light, uSaturation), 0.0);
  float peak = max(light.r, max(light.g, light.b));
  float grain = (fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715)))) - 0.5) / 255.0;
  if (uLight > 0.5) {
    vec3 ink = pow(light / max(peak, 1e-4), vec3(2.0)) * 0.75;
    float alpha = clamp(pow(1.0 - exp(-peak * 2.6), 2.5) * 0.9 * uOpacity + grain, 0.0, 1.0);
    fragColor = vec4(pow(ink, vec3(1.0 / 2.2)) * alpha, alpha);
    return;
  }
  float mapped = 1.0 - exp(-peak);
  vec3 tone = light * (mapped / max(peak, 1e-4));
  tone = mix(tone, vec3(mapped), smoothstep(0.7, 1.0, mapped) * 0.55);
  vec3 shown = clamp(tone * uOpacity, 0.0, 1.0);
  float alpha = max(shown.r, max(shown.g, shown.b));
  vec3 color = clamp(shown * alpha + grain, 0.0, 1.0);
  fragColor = vec4(min(color, vec3(alpha)), alpha);
}`;

export type SideRaysOrigin =
  | 'top-right'
  | 'top-left'
  | 'bottom-right'
  | 'bottom-left'
  | 'right'
  | 'left';

export interface SideRaysProps {
  /** Color of the first layer of rays, on the upper side of the fan. */
  rayColor1?: string;
  /** Color of the second layer of rays, on the lower side of the fan. */
  rayColor2?: string;
  /** Balance between the two layers, from 0 to 1. */
  blend?: number;
  /** Corner or side the light shines in from. */
  origin?: SideRaysOrigin;
  /** How fast the rays shimmer and sway. 0 freezes them. */
  speed?: number;
  /** Brightness of the light. */
  intensity?: number;
  /** How wide the rays fan out. */
  spread?: number;
  /** How many separate rays the light breaks into. */
  density?: number;
  /** How crisp the edges of the rays are, from 0 to 1. */
  sharpness?: number;
  /** Rotates the rays, in degrees. */
  tilt?: number;
  /** How quickly the light fades with distance. */
  falloff?: number;
  /** Brightness of the glow where the light enters. */
  glow?: number;
  /** Color saturation of the light. 0 is grayscale. */
  saturation?: number;
  /** Amount of dust drifting in the light, from 0 to 1. */
  dust?: number;
  /** The rays lean toward the cursor and the ray under it brightens. */
  followMouse?: boolean;
  /** How strongly the rays follow the cursor, from 0 to 1. */
  mouseInfluence?: number;
  /** The rays grow out from their source on mount. */
  intro?: boolean;
  /** Renders the rays as soft tinted light for light backgrounds. */
  lightMode?: boolean;
  /** Overall opacity, from 0 to 1. */
  opacity?: number;
  /** Highest pixel ratio the canvas renders at. */
  maxDevicePixelRatio?: number;
  class?: string;
}

export interface SideRaysFrame {
  flipX: number;
  flipY: number;
  side: number;
}

export interface SideRaysSettings {
  colorA: [number, number, number];
  colorB: [number, number, number];
  blend: number;
  frame: SideRaysFrame;
  speed: number;
  intensity: number;
  spread: number;
  density: number;
  sharpness: number;
  tilt: number;
  falloff: number;
  glow: number;
  saturation: number;
  dust: number;
  followMouse: boolean;
  mouseInfluence: number;
  intro: boolean;
  light: boolean;
  opacity: number;
  maxRatio: number;
  reduce: boolean;
}

export interface SideRaysEngine {
  resize: () => void;
  wake: () => void;
  setVisible: (visible: boolean) => void;
  setPageVisible: (visible: boolean) => void;
  pointerMove: (event: PointerEvent) => void;
  pointerUp: (event: PointerEvent) => void;
  pointerLeave: () => void;
  contextLost: () => void;
  destroy: () => void;
}
